function validate(input) {
  const [{ Sessions = [] }] = input;
  const ids = new Set(), starts = new Set();
  for (const [user, start, end, id, type] of Sessions) {
    if (user === null || start === null || end === null || id === null || type === null) return 'Every session needs all five values.';
    if (ids.has(id)) return `session_id ${id} appears twice.`;
    ids.add(id);
    if (type !== 'Viewer' && type !== 'Streamer') return `session_type ${type} must be Viewer or Streamer.`;
    if (start > end) return `Session ${id} ends before it starts.`;
    const key = `${user}|${start}`;
    if (starts.has(key)) return `User ${user} starts two sessions at ${start}.`;
    starts.add(key);
  }
  return null;
}

