function generate(rand, size) {
  const small = size === 'small';
  const users = small ? 1 + Math.floor(rand() * 4) : 280;
  const limit = small ? 8 : 2000;
  const stamp = minutes => new Date(Date.UTC(2023, 10, 1) + minutes * 60000).toISOString().slice(0, 19).replace('T', ' ');
  const rows = [];
  for (let u = 0; u < users && rows.length < limit; u++) {
    const user = 101 + u;
    const sessions = 1 + Math.floor(rand() * (small ? 3 : 11));
    // Small sets use a coarse grid of start times, so different users often start at the same moment;
    // each user's own start times strictly increase, so they never repeat.
    let slot = Math.floor(rand() * 4);
    for (let i = 0; i < sessions && rows.length < limit; i++) {
      const start = small ? (slot % 3) * 300 + Math.floor(slot / 3) * 1440 + 540 : slot * 37;
      const length = 5 + Math.floor(rand() * 240);
      rows.push([user, stamp(start), stamp(start + length), rand() < 0.5 ? 'Viewer' : 'Streamer']);
      slot += 1 + Math.floor(rand() * 4);
    }
  }
  // Shuffle the rows, then hand out increasing session ids, so id order does not follow time order.
  for (let i = rows.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  let id = 300;
  const Sessions = rows.map(([user, start, end, type]) => [user, start, end, id += 1 + Math.floor(rand() * 9), type]);
  for (let i = Sessions.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Sessions[i], Sessions[j]] = [Sessions[j], Sessions[i]]; }
  return [{ Sessions }];
}
